,1644,1911,NULL,NULL,'清朝'),(9783,'微型叠放盒子模拟食品容器',NULL,'明朝（1368年－1644年）','露西·莫德·白金汉收藏','12.2 × 7.5 × 7.5 厘米（4 13/16 × 3 × 3 英寸）',NULL,NULL,NULL,NULL,'芝加哥艺术学院','中国',NULL,'雕塑','绿釉陶器，釉下模印与刻划装饰',NULL,1368,1644,NULL,NULL,'明朝'),(9789,'四环耳小罐',NULL,'唐朝（618年－907年）','露西·莫德·白金汉收藏','3.9 × 3.4 厘米（1 9/16 × 1 5/16 英寸）；直径：3.4 厘米（1 5/16 英寸）',NULL,NULL,NULL,NULL,'芝加哥艺术学院','中国',NULL,'船只','三彩铅釉陶器带釉下模印装饰',NULL,618,907,NULL,NULL,'唐朝'),(9807,'针线盒',NULL,'清朝（1644-1911年），19世纪','作为塞利姆·沃克·麦克阿瑟博士及夫人的赠礼','8.3 × 12.4 × 21.3 厘米（3 1/4 × 4 7/8 × 8 3/8 英寸）',NULL,NULL,NULL,NULL,'芝加哥艺术学院','中国',NULL,'装饰艺术','象牙',NULL,1644,1911,1800,1900,'清朝'),(9809,'学者隐居处','蔡嘉（1686年—1756年后）','清朝（1644年–1911年），1739年制','由罗伯特·安德鲁·布朗夫妇提供的资金购买','91.5 × 46.3 厘米（36 × 18 1/4 英寸）',NULL,NULL,NULL,NULL,'芝加哥艺术学院','中国',NULL,'绘画','立轴，纸本水墨淡彩','蔡佳',1644,1911,1739,1739,'清朝'),(9872,'墓室支柱',NULL,'西汉（公元前206年–公元9年），公元前1世纪','露西·莫德·白金汉收藏','120.2 × 19 × 18.5 厘米（47 5/16 × 7 1/2 × 7 1/4 英寸）',NULL,'https://www.artic.edu/iiif/2/86574915-5832-cf07-f247-3b199681bdf0/full/843,/0/default.jpg',NULL,'汉代中国北方地区以空心陶砖构筑地下墓室，其形制多为小型长方形。此处复原的墓室入口由门扉、立柱及横楣组成。砖块在烧制前印刻有源自日常生活与神话传说的生动图像。这种题材组合反映了汉代人对灵魂二元性的认知：他们认为人死后灵魂会分离，一部分驻留尘世墓穴，另一部分则升入仙境——那里是先祖之灵与得道成仙者的永恒国度。\n\n每扇门扉中央均饰有写实与象征兼具的守护神像。两名长袍男子（题记为\"亭长\"的乡官）拱卫着具有辟邪功能的环鼻兽面纹。环绕中心方框的边饰带上，可见宴乐场景以及穿行山间的动物、猎手与车马图。羽化登仙的仙人形象亦点缀于山峦纹饰之间。门扉上反复出现的标志性图案还包括：象征家族绵延与长寿的铲形常青树，以及内嵌飞鸟的圆盘（可解读为太阳意象）。\n\n上方横楣处，执盾武士分列于辟邪兽面两侧。兽面两旁以丝带系缚的玉璧纹，可能寓意对亡魂富贵吉祥的祈愿。其他祥瑞符号还包括青龙朱雀（赤鸟）——按汉代宇宙观典籍记载，它们分别代表东方与南方的守护神兽。','芝加哥艺术学院','中国',NULL,'建筑碎片','灰色陶器，饰有压印与雕刻纹样',NULL,-206,-206,0,100,'汉朝；西汉'),(9873,'墓室石柱',NULL,'西汉（公元前206年–公元9年）；公元前1世纪','露西·莫德·白金汉收藏','111.5 × 18 × 17.5 厘米（43 7/8 × 7 1/16 × 6 7/8 英寸）',NULL,'https://www.artic.edu/iiif/2/95ad6d6b-941c-0070-adfe-f8e956a0c9a0/full/843,/0/default.jpg',NULL,'<p>中国汉朝时期，北方地区采用空心陶砖构建地下墓室中的小型矩形墓室。此处组合的门扇、立柱与横梁再现了此类墓室的入口风貌。陶砖在烧制前被压印上源自日常生活与神话传说的生动图案。这种题材的结合体现了古人对灵魂二元性的认知：认为人死后灵魂会分离，一部分驻留于尘世墓穴，另一部分则升入仙境——那里是先祖之灵与得道成仙者的永恒国度。</p>\n<p>每扇门扉中央都装饰着具象与抽象兼具的守护图像。两位长袍男子（题记为\"亭长\"的乡官）拱卫着环形鼻兽面这一辟邪符号。中央方框四周环绕着表现娱乐场景及动物、猎人与战车驰骋山野的边饰带。羽化登仙的仙人——这些精灵般的永生者——同样被描绘于山峦背景中。门扉上反复出现的标志性图案还包括象征家族绵延与长寿的铲形常青树，以及内嵌飞鸟的圆盘（可视为太阳的象征）。</p>\n<p>上方横梁处，持盾武士护卫着辟邪兽面。兽面两侧以丝绦系缚的玉璧，可能寓意灵魂的昌盛或其他吉祥祈愿。其他祥瑞符号还包括青龙朱雀（赤鸟），汉代典籍中将二者分别视为东方与南方的守护神兽。</p>','芝加哥艺术学院','中国',NULL,'建筑碎片','灰色陶器，饰有压印与雕刻纹样',NULL,-206,-206,0,100,'汉朝；西汉'),(9874,'剔红卷草纹圆盒',NULL,'明朝（1368年－1644年）','菲利普·平索夫夫妇捐赠（1961年捐赠六分之一权益）共56件物品','7 × 13.3 厘米（2 13/16 × 5 1/4 英寸）',NULL,NULL,NULL,NULL,'芝加哥艺术学院','中国',NULL,'船只','雕漆',NULL,1368,1644,NULL,NULL,'明朝'),(9876,'牡丹纹盖罐',NULL,'清朝（1644–1911年），18世纪','菲利普·平索夫夫妇赠品','高：11.5厘米（4 1/2英寸）',NULL,NULL,NULL,NULL,'芝加哥艺术学院','中国',NULL,'船只','漆器雕绘装饰',NULL,1644,1911,1700,1800,'清朝'),(9877,'葫芦花卉纹鼻烟壶',NULL,'清朝（1644年—1911年）','菲利普·平索夫夫妇捐赠（1961年捐赠六分之一权益）共56件物品','高：6.4厘米（2 1/2英寸）',NULL,NULL,NULL,NULL,'芝加哥艺术学院','中国',NULL,NULL,'雕红漆',NULL,1644,1911,NULL,NULL,'清朝'),(9878,'牡丹纹鼻烟壶',NULL,'清朝（1644年—1911年）','菲利普·平索夫夫妇捐赠（1961年占六分之一权益）共56件物品','7.8 × 3.8 × 1.8 厘米（3 1/16 × 1 1/2 × 11/16 英寸）',NULL,NULL,NULL,NULL,'芝加哥艺术学院','中国',NULL,NULL,'雕红漆，黄铜底座，玛瑙钮顶',NULL,1644,1911,NULL,NULL,'清朝'),(9879,'凤凰鼻烟壶',NULL,'清朝（1644年—1911年）','菲利普·平索夫夫妇捐赠（1961年捐赠六分之一权益）共56件物品','8.1 × 4.7 × 2.7 厘米（3 3/16 × 1 7/8 × 1 1/16 英寸）',NULL,NULL,NULL,NULL,'芝加哥艺术学院','中国',NULL,NULL,'雕红漆珊瑚钮盖',NULL,1644,1911,NULL,NULL,'清朝'),(9880,'亭园人物图雕漆盒',NULL,'清朝（1644-1911年），18世纪','菲利普·平索夫夫妇捐赠（1961年占六分之一权益）共56件物品','35.6 × 15.3 厘米（14 × 6 英寸）；直径：15.3 厘米（6 英寸）',NULL,NULL,NULL,NULL,'芝加哥艺术学院','中国',NULL,'船只','雕红漆，黄铜底座（？）',NULL,1644,1911,1700,1800,'清朝'),(9886,'两位学者阅读手卷的六角形盒子',NULL,'明朝（1368年－1644年），嘉靖年间（1522年－1566年）','菲利普·平索夫夫妇捐赠（1961年捐赠六分之一权益）共计56件物品','16.9 × 13.3 × 14.9 厘米（6又11/16 × 5又1/4 × 5又7/8英寸）',NULL,NULL,NULL,NULL,'芝加哥艺术学院','中国',NULL,'船只','雕红漆',NULL,1368,1644,66,1522,'明朝'),(9891,'亭台人物雕漆盒',NULL,'明朝（1368年－1644年），宣德年间（1426年－1435年）','菲利普·平索夫夫妇捐赠（1961年捐赠六分之一权益）共计56件物品','11.3 × 13.1 × 8.6 厘米（4 1/2 × 5 3/16 × 3 7/16 英寸）',NULL,NULL,NULL,NULL,'芝加哥艺术学院','中国',NULL,'船只','雕漆',NULL,1368,1644,35,1426,'明朝'),(9892,'花瓶',NULL,'唐朝（618年－907年）','拉塞尔·泰森的礼物','23.2 × 11 厘米（9 1/8 × 4 5/16 英寸）；直径：11 厘米（4 5/16 英寸）',NULL,NULL,NULL,NULL,'芝加哥艺术学院','中国',NULL,'船只','绿釉炻器',NULL,618,907,NULL,NULL,NULL),(9894,'山水人物雕漆盒',NULL,'明朝（1368年—1644年），嘉靖年间（1522年—1566年）','作为菲利普·平索夫夫妇的赠礼（1961年六分之一权益），共56件物品。','31.8 × 22.9 × 8.9 厘米（12 1/2 × 9 × 3 1/2 英寸）',NULL,NULL,NULL,NULL,'芝加哥艺术学院','中国',NULL,'船只','雕漆',NULL,1368,1644,66,1522,'明朝'),(9896,'双狮戏绣球纹盘，环绕吉祥瑞兽',NULL,'明朝（1368年－1644年），嘉靖年间（1522年－1566年）','菲利普·平索夫夫妇赠','3.2 × 18.3 厘米（1 1/4 × 7 3/16 英寸）；直径：18.3 厘米（7 3/16 英寸）',NULL,NULL,NULL,NULL,'芝加哥艺术学院','中国',NULL,'船只','雕漆',NULL,1368,1644,66,1522,'明朝'),(9897,'龙纹盘',NULL,'明朝（1368–1644年），万历年间（1573–1620年），1595年制','菲利普·平索夫夫妇赠品','2.8 × 21.4 厘米（1 1/8 × 8 7/16 英寸）；直径：21.4 厘米（8 7/16 英寸）',NULL,NULL,NULL,NULL,'芝加哥艺术学院','中国',NULL,'船只','雕漆',NULL,1368,1644,1573,1620,'明朝'),(9903,'高足杯',NULL,'明朝（1368年－1644年）','菲利普·平索夫夫妇捐赠（1961年捐赠六分之一权益），共56件物品','高：7.4厘米（2又7/8英寸）',NULL,NULL,NULL,NULL,'芝加哥艺术学院','中国',NULL,NULL,'银胎剔红',NULL,1368,1644,NULL,NULL,'明朝'),(9909,'螺钿酒壶',NULL,'清朝（1644-1911年）','菲利普·平索夫夫妇赠品','整体尺寸：17.8 × 14 厘米（7 × 5 1/2 英寸）；整体直径：14 厘米（5 1/2 英寸）',NULL,NULL,NULL,NULL,'芝加哥艺术学院','中国',NULL,'船舶','锡器上的珍珠母镶嵌',NULL,1644,1911,NULL,NULL,'清朝'),(9910,'梅花树花器',NULL,'清朝（1644年–1911年），1877年','拉塞尔·泰森的遗赠','15.7 × 17.4 × 13.2 厘米（6 3/16 × 6 7/8 × 5 3/16 英寸）',NULL,NULL,NULL,'这件花器上留有19世纪官员学者王凤池的印章与签名。王凤池在江西南康府任职期间，常造访景德镇的御窑厂，并在此觅得新径以寄情书画文墨。他在此类器物上绘制清雅的梅花图案，并配以传世佳句，诠释梅花所象征的祥瑞之气与文人风骨。其构图承袭花鸟画的文学传统，着重体现画意与诗情的交融。','芝加哥艺术学院','中国',NULL,'船只','釉上彩绘瓷器',NULL,1644,1911,1877,1877,'清朝'),(9912,'王羲之观鹅杯',NULL,'清朝（1644–1911年），康熙晚期，18世纪初','拉塞尔·泰森的遗赠','3.4 × 6.8 厘米（1 5/16 × 2 11/16 英寸）；直径：6.8 厘米（2 11/16 英寸）',NULL,NULL,NULL,NULL,'芝加哥艺术学院','中国',NULL,'船只','釉下青花、绿彩、红彩瓷器',NULL,1644,1911,NULL,NULL,'康熙年间；清朝'),(9913,'螺钿镶嵌牡丹亭漆盒',NULL,'清朝（1644–1911年），康熙年间（1662–1722年）','菲利普·平索夫夫妇捐赠（1961年占六分之一份额）共56件物品','3.1 × 10.6 厘米（1 1/4 × 4 3/16 英寸）；直径：10.6 厘米（4 3/16 英寸）',NULL,NULL,NULL,NULL,'芝加哥艺术学院','中国',NULL,'船只','黑漆、螺钿镶嵌与金银箔饰边（？）',NULL,1644,1911,1662,1722,'康熙年间；清朝'),(9923,'锦葵花形盘',NULL,'清朝（1644–1911年），康熙年间（1662–1722年）','菲利普·平索夫夫妇捐赠（1961年占六分之一权益）共56件物品','11.4 × 11.5 × 1.3 厘米（4 1/2 × 4 1/2 × 1/2 英寸）',NULL,NULL,NULL,NULL,'芝