,'清朝（1644-1911年）','露西·莫德·白金汉收藏',NULL,NULL,NULL,NULL,'鼻烟——一种掺入芳香物质的烟草粉末——约在18世纪传入中国。这种需用鼻子吸食的烟草通常储存在小瓶中，瓶塞上配有象牙小勺。鼻烟壶常以珍贵材质制成，如漆器、犀角、螺钿、象牙、金银等。它们小巧玲珑可纳于掌心，却往往展现出非凡工艺与艺术匠心，成为中外收藏界广受欢迎的珍品。\n\n此件鼻烟壶周身装饰繁复的镶嵌纹样，营造出层次丰富的立体画面。一侧描绘仕女于梨树下漫步庭园，另一侧透过屏风展现半室内景致：枝头红鹦鹉俯视着下方香炉。这般构图显然借鉴了传统绘画意境。当聪慧却常被囚笼的鹦鹉与孤身女子形象并置时，或许暗喻着传统社会闺阁女性内心的孤寂与渴望。','芝加哥艺术学院','中国',NULL,'船只','漆器镶嵌',NULL,1644,1911,NULL,NULL,'清朝'),(10508,'山水鼻烟壶',NULL,'清朝（1644-1911年）','露西·莫德·白金汉收藏',NULL,NULL,NULL,NULL,NULL,'芝加哥艺术学院','中国',NULL,'船只','象牙',NULL,1644,1911,NULL,NULL,'清朝'),(10509,'龙纹鼻烟壶',NULL,'清朝（1644-1911年）','露西·莫德·白金汉收藏',NULL,NULL,NULL,NULL,NULL,'芝加哥艺术学院','中国',NULL,'船只','漆朱砂',NULL,1644,1911,NULL,NULL,'清朝'),(10510,'双人图鼻烟壶',NULL,'清朝（1644-1911年）','露西·莫德·白金汉藏品',NULL,NULL,NULL,NULL,NULL,'芝加哥艺术学院','中国',NULL,'船只','象牙雕刻',NULL,1644,1911,NULL,NULL,'清朝'),(10511,'童子鼻烟壶',NULL,'清朝（1644-1911年）','露西·莫德·白金汉收藏',NULL,NULL,NULL,NULL,NULL,'芝加哥艺术学院','中国',NULL,'船只','漆朱砂',NULL,1644,1911,NULL,NULL,'清朝'),(10526,'鼻烟壶',NULL,'清朝（1644年—1911年）','露西·莫德·白金汉收藏','高：6.4厘米（2 1/2英寸）',NULL,NULL,NULL,NULL,'芝加哥艺术学院','中国',NULL,'船只','青釉瓷器',NULL,1644,1911,NULL,NULL,'清朝'),(10558,'鼻烟壶',NULL,'清朝（1644年—1911年）','露西·莫德·白金汉收藏',NULL,NULL,NULL,NULL,NULL,'芝加哥艺术学院','中国',NULL,'船只','条纹玛瑙，珊瑚塞带底座',NULL,1644,1911,NULL,NULL,'清朝'),(10595,'辣椒形鼻烟壶',NULL,'清朝（1644年—1911年）','露西·莫德·白金汉收藏','高：7.7厘米（3英寸）',NULL,NULL,NULL,NULL,'芝加哥艺术学院','中国',NULL,'船只','绿釉瓷器',NULL,1644,1911,NULL,NULL,'清朝'),(10605,'鼻烟壶',NULL,'清朝（1644年—1911年）','露西·莫德·白金汉收藏','高：5.8厘米（2又1/4英寸）',NULL,NULL,NULL,NULL,'芝加哥艺术学院','中国',NULL,'船只','蜜色琥珀',NULL,1644,1911,NULL,NULL,'清朝'),(10606,'鼻烟壶',NULL,'清朝（1644年—1911年）','露西·莫德·白金汉收藏','高：5.8厘米（2又1/4英寸）',NULL,NULL,NULL,NULL,'芝加哥艺术学院','中国',NULL,'船只','琥珀',NULL,1644,1911,NULL,NULL,'清朝'),(10607,'骆驼',NULL,'唐朝（公元618年–907年），8世纪上半叶','伯莎·帕尔默·索恩的礼物',NULL,NULL,'https://www.artic.edu/iiif/2/c02ac167-54bc-ec04-19da-72e4a73326aa/full/843,/0/default.jpg',NULL,'一件采用三彩铅釉制作的陶器作品。','芝加哥艺术学院','中国',NULL,'雕塑','三彩铅釉陶器',NULL,618,907,700,800,'唐朝'),(10608,'骑手',NULL,'唐朝（公元618-907年），8世纪上半叶','伯莎·帕尔默·索恩的礼物',NULL,NULL,