NULL),(10656,'绿松石鼻烟壶',NULL,'清朝（1644-1911年）','凯瑟琳·S·巴金汉姆小姐赠予露西·莫德·巴金汉姆收藏品\n\n露西·莫德·巴金汉姆纪念',NULL,NULL,NULL,NULL,NULL,'芝加哥艺术学院','中国',NULL,'船只','绿松石',NULL,1644,1911,NULL,NULL,'清朝'),(10689,'花鸟纹鼻烟壶',NULL,'清朝（1644-1911年）','凯瑟琳·S·巴金汉姆小姐赠予露西·莫德·巴金汉姆收藏\n\n露西·莫德·巴金汉姆纪念',NULL,NULL,NULL,NULL,NULL,'芝加哥艺术学院','中国',NULL,'船只','绿松石',NULL,1644,1911,NULL,NULL,'清朝'),(10692,'葫芦形鼻烟壶',NULL,'清朝（1644-1911年）','露西·莫德·白金汉收藏',NULL,NULL,NULL,NULL,NULL,'芝加哥艺术学院','中国',NULL,'船只','绿松石基质',NULL,1644,1911,NULL,NULL,'清朝'),(10693,'松鼠与葡萄','沈永令（中国，1614-1698）','1694年 清朝','塞缪尔·M·尼克森捐赠基金','84.7 × 30.6 厘米（33 1/4 × 12 1/4 英寸）',NULL,'https://www.artic.edu/iiif/2/8c56e29b-6b6f-394d-3a62-21c811932b72/full/843,/0/default.jpg',NULL,'一幅立轴作品；纸本水墨设色。','芝加哥艺术学院','中国',NULL,'绘画','挂轴；纸本水墨设色',NULL,1694,1694,NULL,NULL,NULL),(10694,'梅花纹鼻烟壶',NULL,'清朝（1644-1911年）','露西·莫德·白金汉收藏','高：5.1厘米（2英寸）',NULL,NULL,NULL,NULL,'芝加哥艺术学院','中国',NULL,'船只','雕刻珊瑚',NULL,1644,1911,NULL,NULL,'清朝'),(10696,'松鼠鼻烟壶',NULL,'清朝（1644-1911年）','露西·莫德·白金汉收藏',NULL,NULL,NULL,NULL,NULL,'芝加哥艺术学院','中国',NULL,'船只','珊瑚，珍珠塞，象牙座。',NULL,1644,1911,NULL,NULL,'清朝'),(10697,'覆盖物',NULL,'明朝（1368–1644）/清朝（1644–1911），17世纪中叶','詹姆斯·D·蒂格曼遗产捐赠','263.2 × 222.2 厘米（103 5/8 × 87 1/2 英寸）',NULL,'https://www.artic.edu/iiif/2/d36df308-90b1-59e4-bde1-dd1511d869d2/full/843,/0/default.jpg',NULL,'一件以缎纹组织丝绸制成的作品；采用丝线与金箔覆盖漆纸包裹棉线，运用中国结、网眼、羽毛、缎纹、单缎纹、劈针及茎绣针法刺绣；辅以铺绣与钉线工艺；内衬为平纹亚麻布；里料为平纹棉布；边缘饰以成对经线的平纹丝绸滚边。','芝加哥艺术学院','中国',NULL,'纺织品','丝绸，缎纹组织；以丝线和金箔覆盖的漆纸包裹棉线，采用中国结、网眼、羽毛、缎纹、单缎纹、劈线及茎线针法刺绣；辅以亚麻平纹布衬里；棉质平纹布内衬；边缘饰以成对经线的丝绸平纹织物。',NULL,1368,1644,1600,1700,'明朝；清朝'),(10700,'滚动',NULL,'明朝（1368–1644）/清朝（1644–1911），17世纪','詹姆斯·D·蒂格曼遗产的馈赠','183.6 × 56.5 厘米（72 1/4 × 22 1/4 英寸）',NULL,'https://www.artic.edu/iiif/2/c10beb31-bd85-1b5b-4088-2f2b493c4c18/full/843,/0/default.jpg',NULL,'作品中央面板材质：丝绸，缎纹组织；采用中国结、缎绣及茎绣技法以丝线刺绣  \n外轴下端装裱及残片：丝绸，缎地暗花织物  \n绳饰：人造丝，棉芯编织而成。','芝加哥艺术学院','中国',NULL,'纺织品','中心面板：丝绸，缎纹组织；用丝线以中国结、缎纹和茎线针法刺绣\n外卷轴下端装裱及碎片：丝绸，缎纹提花织物\n绳带：人造丝，棉芯编织',NULL,1368,1644,1600,1700,'明朝；清朝'),(10701,'滚动',NULL,'清朝（1644–1911年），约1860年','詹姆斯